        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return base.FillRecordType(
                            stream: stream,
                            finalPos: finalPos,
                            offset: offset,
                            type: type,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        _EDIDLocation = (stream.Position - offset);
                        return new ParseResult((int)Explosion_FieldIndex.EDID, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                return base.FillRecordType(
                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)Explosion_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.OPDS:
                {
                    this.ObjectPlacementDefaults = BinaryOverlayList.FactoryByArray<IObjectPlacementDefaultGetter>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ObjectPlacementDefaultBinaryOverlay.ObjectPlacementDefaultFactory(new OverlayStream(s, p), p, recConv),
                        locs: ParseRecordLocations(
                            stream: stream,
                            trigger: ObjectPlacementDefault_Registration.TriggerSpecs,
                            triggersAlwaysAreNewRecords: true,
                            constants: _package.MetaData.Constants.SubConstants,
                            skipHeader: false));
                    return (int)Explosion_FieldIndex.ObjectPlacementDefaults;
                }
                case RecordTypeInts.OBND:
                {
                    _ObjectBoundsLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Explosion_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.PHST:
                {
                    _PHSTLocation = (stream.Position - offset);
                    return (int)Explosion_FieldIndex.PHST;
                }
                case RecordTypeInts.FULL:
                {
                    _FULLLocation = (stream.Position - offset);
                    return (int)Explosion_FieldIndex.FULL;
                }
                case RecordTypeInts.DESC:
                {
                    _DESCLocation = (stream.Position - offset);
                    return (int)Explosion_FieldIndex.DESC;
                }
                case RecordTypeInts.MODL:
                case RecordTypeInts.MODC:
                case RecordTypeInts.MODT:
                case RecordTypeInts.MODS:
                {
                    this.Model = ModelBinaryOverlay.ModelFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Explosion_FieldIndex.Model;
                }
                case RecordTypeInts.EITM:
                {
                    _EnchantmentLocation = (stream.Position - offset);
                    return (int)Explosion_FieldIndex.Enchantment;
                }
                case RecordTypeInts.MNAM:
                {
                    _ImageSpaceModifierLocation = (stream.Position - offset);
                    return (int)Explosion_FieldIndex.ImageSpaceModifier;
                }
                case RecordTypeInts.DATA:
                {
                    _DATALocation = (stream.Position - offset);
                    return (int)Explosion_FieldIndex.DATA;
                }
                case RecordTypeInts.DAMA:
                {
                    _DAMALocation = (stream.Position - offset);
                    return (int)Explosion_FieldIndex.DAMA;
